<?php require "config.php";require_admin();$page_title="Dashboard | SFHS";$statuses=["New","In Review","Action Taken","Closed"];$counts=array_fill_keys($statuses,0);$r=$conn->query("SELECT status,COUNT(*) n FROM complaints GROUP BY status");while($x=$r->fetch_assoc())$counts[$x["status"]]=(int)$x["n"];$filter=$_GET["status"]??"";if(in_array($filter,$statuses,true)){$s=$conn->prepare("SELECT id,tracking_code,category,subject,is_anonymous,reporter_name,status,created_at FROM complaints WHERE status=? ORDER BY created_at DESC");$s->bind_param("s",$filter);}else{$s=$conn->prepare("SELECT id,tracking_code,category,subject,is_anonymous,reporter_name,status,created_at FROM complaints ORDER BY created_at DESC");}$s->execute();$rows=$s->get_result();require "includes/header.php"; ?>
<div class="admin"><aside class="sidebar"><?php require "includes/sidebar.php"; ?></aside><section><div class="dashhead"><div><span class="eyebrow">ADMIN OVERVIEW</span><h1>Welcome, <?=e($_SESSION["admin_name"]??"Administrator")?></h1><p class="muted">Review and manage complaint records.</p></div><a class="btn" href="export.php">Export CSV</a></div><div class="grid stats"><a class="panel" href="dashboard.php"><small>Total</small><h2><?=array_sum($counts)?></h2></a><?php foreach($counts as $st=>$n): ?><a class="panel" href="dashboard.php?status=<?=urlencode($st)?>"><small><?=e($st)?></small><h2><?=$n?></h2></a><?php endforeach; ?></div><div class="panel" id="records"><div class="dashhead"><h2>Complaint records</h2><form method="get"><select name="status"><option value="">All statuses</option><?php foreach($statuses as $st): ?><option <?=($filter===$st?"selected":"")?>><?=e($st)?></option><?php endforeach; ?></select><button class="btn smallbtn">Filter</button></form></div><div class="scroll"><table><thead><tr><th>Reference</th><th>Category</th><th>Subject</th><th>Reporter</th><th>Status</th><th>Date</th><th></th></tr></thead><tbody><?php if(!$rows->num_rows): ?><tr><td colspan="7">No records yet.</td></tr><?php endif; ?><?php while($x=$rows->fetch_assoc()): ?><tr><td><?=e($x["tracking_code"])?></td><td><?=e($x["category"])?></td><td><?=e($x["subject"])?></td><td><?=$x["is_anonymous"]?"Anonymous":e($x["reporter_name"])?></td><td><?=e($x["status"])?></td><td><?=e(date("M d, Y",strtotime($x["created_at"])))?></td><td><a href="view.php?id=<?=(int)$x["id"]?>">Review</a></td></tr><?php endwhile; ?></tbody></table></div></div></section></div><?php $s->close();require "includes/footer.php"; ?>